// Renewal applications share the existing approval queue and subject tabs.
for(const [kind,sourceIndex,expiry,days] of [['personal',0,'2026-11-12',180],['enterprise',0,'2026-11-01',90],['agent',0,'2026-12-01',180]]){
 const subject=identityExamples[kind][sourceIndex];
 identityExamples[kind].push({...subject,type:'续期',submitted:'2026-11-06 09:30:00',renewal:{firstRenewal:kind==='agent'?'':'2026-05-16',expiry,days,reason:'申请延长主体身份有效期，继续办理相关业务。'}});
}
function identityRenewalDate(expiry,days,approvedAt){
 const day=approvedAt||new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});
 const base=expiry>day?expiry:day,date=new Date(base+'T00:00:00+08:00');
 date.setUTCDate(date.getUTCDate()+Number(days));
 return new Date(date.getTime()+8*3600000).toISOString().slice(0,10);
}
let identityQueue='pending',identityKind='personal',identityMenuOpen=true;
const identityViews={};
const identityPage=()=>`identity-${identityQueue}-${identityKind}`;
const identityReq=(module,element=module)=>req(`identity.review.${identityQueue}.${identityKind}.${module}`,`identity.review.${identityQueue}.${identityKind}.${element}`);
function identityView(){return identityViews[identityPage()] ||= {draft:{},filters:{},page:1,size:10};}
function identityOpen(queue='pending',kind='personal'){
 identityQueue=queue==='completed'?'completed':'pending';identityKind=identityKinds[kind]?kind:'personal';section='identity';$('#overlay').innerHTML='';document.querySelector('#audit')?.remove();
 const u=new URL(location.href);u.searchParams.set('system','identity');u.searchParams.set('view',identityQueue);u.searchParams.set('kind',identityKind);history.replaceState(null,'',u);render();
}
function identityQuery(reset=false){const v=identityView();if(reset){v.draft={};v.filters={};}else v.filters=Object.fromEntries(Object.entries(v.draft).map(([k,value])=>[k,value.trim()]));v.page=1;identityRender();}
function identityRender(){
 const completed=identityQueue==='completed',title=completed?'我已审批':'待我审批',schema=identitySchemas[identityKind],v=identityView();
 document.querySelector('header b').textContent='主体身份管理系统';
 $('#sidebar').innerHTML=`<button class="identity-menu nav" aria-expanded="${identityMenuOpen}" onclick="identityMenuOpen=!identityMenuOpen;identityRender()"><span>▣</span>审核管理<em>${identityMenuOpen?'⌄':'›'}</em></button>${identityMenuOpen?['pending','completed'].map(q=>`<button class="identity-menu nav identity-sub ${identityQueue===q?'active':''}" onclick="identityOpen('${q}',identityKind)">${q==='pending'?'待我审批':'我已审批'}</button>`).join(''):''}<button class="identity-menu nav identity-return" onclick="section='launch';history.replaceState(null,'','?system=management');render()"><span>⇤</span>返回快捷入口</button>`;
 const fields=[...schema.fields,...(completed?[['result','审核结果',['通过','驳回']]]:[])];
 let list=identityExamples[identityKind].map((r,i)=>({...r,_index:i,...(completed?{type:r.type,result:i%3===1?'驳回':'通过'}:{}),...(identityDecisions[identityKind+'.'+i]||{})})).filter(r=>completed||!identityDecisions[identityKind+'.'+r._index]).filter(r=>Object.entries(v.filters).every(([k,value])=>!value||(fields.find(f=>f[0]===k)?.[2]?r[k]===value:String(r[k]||'').includes(value))));
 const pages=Math.max(1,Math.ceil(list.length/v.size));v.page=Math.min(v.page,pages);
 const columns=[...schema.columns,...(completed?[['result','审核结果']]:[])];
 $('#main').innerHTML=`<div class="systemtabs"><span onclick="section='launch';history.replaceState(null,'','?system=management');render()">首页</span><span class="selected">● ${title}</span></div><div class="identity-page" data-req-page="${identityPage()}" data-req-surface="${identityPage().replaceAll('-','.')}" data-req-title="${title} · ${identityKinds[identityKind]}"><div class="identity-tabs" role="tablist" aria-label="主体类型" ${identityReq('list','tabs')}>${Object.entries(identityKinds).map(([k,n])=>`<button role="tab" aria-selected="${k===identityKind}" class="${k===identityKind?'active':''}" onclick="identityOpen(identityQueue,'${k}')" ${identityReq('list','tab.'+k)}>${n}</button>`).join('')}</div><form class="identity-filters" onsubmit="event.preventDefault();identityQuery()" ${identityReq('query')}>${fields.map(([k,n,options])=>`<label ${identityReq('query','field.'+k)}><span>${n}</span>${options?`<select name="${k}" onchange="identityView().draft[this.name]=this.value"><option value="">请选择</option>${options.map(x=>`<option ${v.draft[k]===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:`<input name="${k}" aria-label="${n}" placeholder="请输入" maxlength="100" value="${esc(v.draft[k]||'')}" oninput="identityView().draft[this.name]=this.value">`}</label>`).join('')}<div class="identity-query-actions"><button class="btn primary" type="submit" ${identityReq('query','query.submit')}>⌕ 查询</button><button class="btn" type="button" onclick="identityQuery(true)" ${identityReq('query','query.reset')}>↻ 重置</button></div></form><section class="identity-results" ${identityReq('list')} aria-label="${identityKinds[identityKind]}${title}列表"><div class="identity-table-tools">${!completed?identityPendingTags(identityKind):''}<button type="button" aria-label="刷新列表" title="刷新列表" onclick="identityRender()" ${identityReq('list','refresh')}>↻</button></div><div class="identity-table-scroll"><table><thead><tr>${columns.map(([k,n])=>`<th>${n}</th>`).join('')}<th>操作</th></tr></thead><tbody>${list.slice((v.page-1)*v.size,v.page*v.size).map(r=>`<tr>${columns.map(([k])=>`<td title="${esc(r[k]||'—')}">${k==='type'||k==='result'?`<span class="identity-badge ${k==='result'?(r[k]==='通过'?'green':'red'):r[k]==='更新'?'orange':''}">${esc(r[k])}</span>`:esc(r[k]||'—')}</td>`).join('')}<td><button type="button" class="link" onclick="identityAuditOpen(${r._index})" ${identityReq('list',completed?'record.view':'approval.open')}>${completed?'查看':'♟ 审批'}</button></td></tr>`).join('')||`<tr><td colspan="${columns.length+1}" class="empty">暂无匹配记录</td></tr>`}</tbody></table></div><div class="identity-pagination" ${identityReq('list','pagination')}><span>共 ${list.length} 条</span><select aria-label="每页条数" onchange="identityView().size=Number(this.value);identityView().page=1;identityRender()">${[10,20,50].map(n=>`<option value="${n}" ${n===v.size?'selected':''}>${n}条/页</option>`).join('')}</select><button ${v.page===1?'disabled':''} aria-label="上一页" onclick="identityView().page--;identityRender()">‹</button><b>${v.page}</b><button ${v.page===pages?'disabled':''} aria-label="下一页" onclick="identityView().page++;identityRender()">›</button><label>前往 <input type="number" aria-label="跳转页码" min="1" max="${pages}" value="${v.page}" onchange="identityView().page=Math.max(1,Math.min(${pages},Math.floor(Number(this.value)||1)));identityRender()"> 页</label></div></section></div>`;
 window.dispatchEvent(new CustomEvent('ai-prototype:context-changed'));
}
const identityPreviousRender=render;
render=function(){if(section==='identity'){identityRender();return;}identityPreviousRender();};
document.addEventListener('click',event=>{if(event.target.closest('.cards > .card[data-req-id="system.2"]')){event.preventDefault();event.stopImmediatePropagation();selectSystem(2);identityOpen();}},true);
if(new URLSearchParams(location.search).get('system')==='identity'){const p=new URLSearchParams(location.search);identityOpen(p.get('view'),p.get('kind'));}

const identityAuditModule=(name,element=name)=>req(`identity.review.${identityAudit.kind}.audit.${name}`,`identity.review.${identityAudit.kind}.audit.${element}`);
function identityAuditOpen(index){
 const source=identityExamples[identityKind][index],decision=identityDecisions[identityKind+'.'+index];
 const row={...source,...(identityQueue==='completed'&&!decision?{type:source.type,result:index%3===1?'驳回':'通过'}:{}),...(decision||{})};
 identityAudit={kind:identityKind,index,row,type:row.type,readOnly:identityQueue==='completed',historyType:'全部',historyOpen:false,drafts:{},material:null,confirm:false,error:''};
 ['header','#sidebar','#main'].forEach(selector=>{const element=document.querySelector(selector);if(element)element.inert=true;});
 identityAuditRender();$('#overlay [role="dialog"]').focus();
}
function identityAuditDraft(){return identityAudit.drafts[identityAudit.type] ||= {result:'',opinion:''};}
function identityAuditSwitch(type){identityAudit.type=type;identityAudit.confirm=false;identityAudit.error='';identityAudit.material=null;identityAuditRender();}
function identityAuditClose(){['header','#sidebar','#main'].forEach(selector=>{const element=document.querySelector(selector);if(element)element.inert=false;});identityAudit=null;$('#overlay').innerHTML='';window.dispatchEvent(new CustomEvent('ai-prototype:context-changed'));document.querySelector('.identity-results .link')?.focus();}
function identityAuditHistory(){
 const a=identityAudit,base=[
 {type:'注册',date:'2026-06-01 10:25:10',result:'通过',operator:'运营审核员',opinion:'认证信息完整，与所提交材料一致。'},
 {type:'更新',date:'2026-07-15 14:32:06',result:'驳回',operator:'运营审核员',opinion:'申请更新的信息与证明材料不一致，请补充有效材料。'},
 {type:'更新',date:'2026-07-16 09:18:30',result:'通过',operator:'运营审核员',opinion:'已补充证明材料，更新信息核验通过。'},
 {type:'冻结操作',date:'2026-08-12 11:20:00',result:'通过',operator:'运营审核员',opinion:'依据已提交的风险说明冻结该主体身份。'},
 {type:'解冻',date:'2026-08-20 16:45:22',result:'通过',operator:'运营审核员',opinion:'整改材料已补充，申请恢复身份可用。'},
 ...(a.row.renewal?.firstRenewal?[{type:'续期',date:a.row.renewal.firstRenewal+' 10:00:00',result:'通过',operator:'运营审核员',opinion:'主体身份续期180天，审核通过。'}]:[]),
 {type:'注销',date:'2026-09-03 10:09:00',result:'驳回',operator:'运营审核员',opinion:'未完成关联业务核对，请补充注销说明。'}
 ];
 const frozen=window.IdentityWorkflowData.freeze(a.kind,a.row);if(frozen)base.push({type:'冻结操作',date:frozen.date,result:'已冻结',operator:'当前运营人员',opinion:frozen.reason});
 const saved=identityDecisions[a.kind+'.'+a.index];if(saved)base.push({type:saved.type,date:saved.reviewedAt,result:saved.result,operator:'当前运营人员',opinion:saved.opinion||'审核通过。'});
 return base.filter(r=>a.historyType==='全部'||r.type===a.historyType).sort((a,b)=>b.date.localeCompare(a.date));
}
function identityAuditRender(){
 const a=identityAudit;if(!a)return;const scrollTop=document.querySelector('.identity-audit-information')?.scrollTop||0;const personal=a.kind==='personal',draft=identityAuditDraft(),preview=a.type!==a.row.type;
 const context={续期:['主体身份有效期续期审核','核对当前有效期和申请续期时长，确认续期后到期时间。','审核通过后延长主体身份有效期'],注册:['新主体身份注册审核','核对申请人的认证信息与证件材料，确认身份信息真实、完整、一致。','未注册 → 审核通过后完成身份注册'],更新:['主体认证信息更新审核','重点核对变更字段及证明材料，确认申请更新的信息有据可查。','可用 → 审核通过后更新认证信息'],解冻:['主体身份解冻审核','核对解冻申请说明及整改材料，确认恢复身份使用的依据。','冻结 → 审核通过后恢复可用'],注销:['主体身份注销审核','核对注销意愿、申请说明与相关材料，审慎确认注销申请。','可用 → 审核通过后注销']}[a.type];
 const groups=window.IdentityCertification.groups(a.kind,a.type==='续期'?{...a.row,expiresAt:a.row.renewal?.expiry}:a.row),surface=`identity.review.${a.kind}.audit.${a.type==='注册'?'register':a.type==='更新'?'update':a.type==='续期'?'renew':a.type==='解冻'?'unfreeze':'cancel'}`;
 $('#overlay').innerHTML=`<div class="identity-audit-veil"><section class="identity-audit-dialog" role="dialog" aria-modal="true" tabindex="-1" aria-labelledby="identity-audit-title" data-req-page="${identityPage()}" data-req-surface="${surface}" data-req-layer="dialog" data-req-title="${identityKinds[a.kind]}${a.type}审核"><div class="identity-audit-header" ${identityAuditModule('context')}><div><span class="identity-audit-eyebrow">主体身份审核 · ${identityKinds[a.kind]}</span><h1 id="identity-audit-title">${a.type}审核 <span class="identity-audit-state">${a.readOnly?(a.row.result||'通过'):'待我审批'}</span></h1></div><button class="identity-audit-close" aria-label="关闭审核弹窗" onclick="identityAuditClose()">×</button></div><div class="identity-audit-scenarios" ${identityAuditModule('context','type.switch')}><span>审核类型</span><div role="tablist" aria-label="切换审核类型">${identityTypes.map(t=>`<button role="tab" aria-selected="${a.type===t}" class="${a.type===t?'active':''}" onclick="identityAuditSwitch('${t}')">${t}</button>`).join('')}</div><button class="identity-history-entry" onclick="identityAudit.historyOpen=!identityAudit.historyOpen;if(identityAudit.historyOpen)identityAudit.historyType='全部';identityAuditRender()" ${identityAuditModule('history','history.open')}>◷ ${a.historyOpen?'返回审核':'审核历史记录'}</button></div><p class="identity-audit-demo-hint">此处多个审核类型弹窗仅作原型展示，真实审核流每次只有一个审核类型。</p><div class="identity-audit-layout ${a.historyOpen?'identity-history-mode':''}">${a.historyOpen?identityAuditHistoryPanel():''}<div class="identity-audit-information"><section class="identity-audit-focus" ${identityAuditModule('context','subject')}><span class="identity-audit-focus-icon">${personal?'♙':'▥'}</span><div><h2>${esc(a.row.name)}</h2><p>${personal?'证件号码':a.kind==='agent'?'经办人标识':'统一社会信用代码'}：${esc(a.row.code)}</p><p>提交人：${esc(a.row.submitter)} <span>提交时间：${esc(a.row.submitted)}</span></p></div><div class="identity-audit-ref"><span>申请编号</span><strong>CQ-${personal?'P':'E'}-20261104-${String(a.index+1).padStart(3,'0')}</strong></div></section><section class="identity-audit-section" ${identityAuditModule('request')}><div class="identity-audit-section-title"><h2>本次${a.type}申请</h2><span>${context[0]}</span></div><div class="identity-audit-request">${a.type==='更新'?`<table class="identity-audit-diff"><thead><tr><th>变更字段</th><th>变更前</th><th>本次申请值</th></tr></thead><tbody><tr><td>${personal?'证件有效期':a.kind==='agent'?'所属组织名称':'经营期限'}</td><td>${personal?'2019-07-02 至 2029-07-02':a.kind==='agent'?esc(a.row.organization)+'（原名称）':'2024-10-30 至 2034-10-29'}</td><td><strong>${personal?'2019-07-02 至 2035-07-02':a.kind==='agent'?esc(a.row.organization):'2024-10-30 至 长期'}</strong></td></tr></tbody></table>`:a.type==='注册'?'<dl><dt>申请说明</dt><dd>申请注册主体身份，已提交认证信息及相关证明材料。</dd></dl>':a.type==='续期'?identityRenewalFields():a.type==='解冻'?identityUnfreezeFields():`<dl><dt>${a.type}原因</dt><dd>${{解冻:'相关问题已完成整改，申请解除冻结并恢复身份使用。',注销:'申请终止该主体身份使用，请审核注销信息与证明材料。'}[a.type]}</dd></dl>`}</div></section><section class="identity-audit-section" ${identityAuditModule('info')}><div class="identity-audit-section-title"><h2>基本信息</h2></div>${groups.map(group=>group.permissions?identityAgentPermissionBlock(group):group.signature?identityAgentSignatureBlock(group):group.materials?`<div class="identity-audit-info-group" ${identityAuditModule('materials','materials.'+groups.indexOf(group))}><h3>${group.title}</h3><div class="identity-audit-files">${group.rows.map(([label,file])=>`<button onclick="identityAuditMaterial('${file}')"><span class="identity-audit-file-icon">${file.endsWith('.csr')?'CSR':file.endsWith('.pdf')?'PDF':'IMG'}</span><span><strong>${esc(label)}</strong><small>${file}</small></span><em>查看</em></button>`).join('')}</div></div>`:`<div class="identity-audit-info-group"><h3>${group.title}</h3><dl class="identity-audit-fields">${group.rows.map(([name,value,wide])=>`<div class="${wide?'wide':''}"><dt>${window.IdentityCertification.isRequired(a.kind,name)?'<em class="identity-required" aria-label="必填">*</em>':''}${esc(name)}</dt><dd>${esc(name==='申请状态'?(a.readOnly?(a.row.result||'通过'):'待审核'):value)}</dd></div>`).join('')}</dl></div>`).join('')}${a.material?`<div class="identity-audit-material-note" role="status"><strong>材料查看 · ${esc(a.material)}</strong><button class="link" onclick="identityAudit.material=null;identityAuditRender()">收起</button></div>`:''}</section></div><aside class="identity-audit-decision" ${identityAuditModule('decision')}><div class="identity-audit-decision-heading"><span>审核工作区</span><h2>${a.readOnly?'审核结果':'请完成'+a.type+'审核'}</h2></div>${a.readOnly?`<div class="identity-audit-read-result"><span class="identity-badge ${(a.row.result||'通过')==='通过'?'green':'red'}">${esc(a.row.result||'通过')}</span><dl><dt>审核人</dt><dd>当前运营人员</dd><dt>审核时间</dt><dd>${esc(a.row.reviewedAt||(a.type==='续期'?'2026-11-06 10:00:00':'2026-11-04 09:20:00'))}</dd><dt>审核意见</dt><dd>${esc(a.row.opinion||((a.row.result||'通过')==='通过'?'认证信息与证明材料一致，审核通过。':'申请资料不完整，请补充有效证明材料。'))}</dd></dl></div>`:`<form id="identity-audit-form" onsubmit="event.preventDefault();identityAuditConfirm()"><fieldset><legend>审核结果 <em>*</em></legend><label class="identity-audit-choice ${draft.result==='通过'?'selected':''}"><input type="radio" name="audit-result" value="通过" ${draft.result==='通过'?'checked':''} onchange="identityAuditDraft().result=this.value;identityAudit.confirm=false;identityAuditRender()">通过</label><label class="identity-audit-choice ${draft.result==='驳回'?'selected':''}"><input type="radio" name="audit-result" value="驳回" ${draft.result==='驳回'?'checked':''} onchange="identityAuditDraft().result=this.value;identityAudit.confirm=false;identityAuditRender()">驳回</label></fieldset><label class="identity-audit-opinion">审核意见 ${draft.result==='驳回'?'<em>*</em>':'<span>（选填）</span>'}<textarea aria-label="审核意见" maxlength="500" placeholder="${draft.result==='驳回'?'请填写驳回原因，便于申请人补充或修改资料':'请输入审核意见'}" oninput="identityAuditDraft().opinion=this.value;identityAudit.confirm=false">${esc(draft.opinion)}</textarea></label><p class="identity-audit-error" role="alert">${esc(a.error)}</p><div class="identity-audit-submit"><button type="submit" class="btn primary" ${preview?'disabled':''}>提交审核</button></div></form>`}</aside></div></section></div>${a.confirm?identityAuditConfirmation():''}`;
 const information=document.querySelector('.identity-audit-information');if(information)information.scrollTop=scrollTop;
 const mainDialog=document.querySelector('.identity-audit-dialog');if(mainDialog)mainDialog.inert=!!a.confirm;
 if(a.confirm)document.querySelector('.identity-audit-confirm-dialog [data-confirm-cancel]')?.focus();
 window.dispatchEvent(new CustomEvent('ai-prototype:context-changed'));
}
function identityAuditMaterial(file){identityAudit.material=file;identityAuditRender();document.querySelector('.identity-audit-material-note')?.scrollIntoView({block:'center'});}
function identityAuditConfirm(){const a=identityAudit,d=identityAuditDraft();a.error=!d.result?'请选择审核结果。':d.result==='驳回'&&!d.opinion.trim()?'请填写驳回原因。':d.opinion.trim().length>500?'审核意见最多 500 字。':'';if(!a.error&&a.type==='续期'){const r=a.row.renewal;if(!r||!/^\d{4}-\d{2}-\d{2}$/.test(r.expiry)||!Number.isFinite(Date.parse(r.expiry))||!Number.isInteger(r.days)||r.days<1||r.days>180)a.error='请核对当前到期时间和续期时长，单次续期必须为1–180天的整数。';}if(!a.error&&a.type==='解冻'){const data=window.IdentityWorkflowData.unfreeze(a.kind,a.row);if(!data.freezeReason||!data.reason||!/^1[3-9]\d{9}$/.test(data.phone))a.error='冻结原因、申诉说明和有效的申诉联系电话均为必填，请核对关联的冻结记录与解冻申请。';}a.confirm=!a.error;identityAuditRender();}
function identityAuditSubmit(){const a=identityAudit,d=identityAuditDraft();if(!a.confirm||a.readOnly||a.type!==a.row.type||!d.result||(d.result==='驳回'&&!d.opinion.trim()))return;const reviewedAt=new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'});identityDecisions[a.kind+'.'+a.index]={type:a.type,result:d.result,opinion:d.opinion.trim(),reviewedAt,...(a.type==='续期'?{renewal:{...a.row.renewal,effectiveExpiry:d.result==='通过'?identityRenewalDate(a.row.renewal.expiry,a.row.renewal.days,reviewedAt.slice(0,10)):a.row.renewal.expiry}}:{})};identityAuditClose();identityRender();toast('审核结果已记录');}
document.addEventListener('keydown',event=>{if(!identityAudit)return;if(event.key==='Escape'){event.preventDefault();if(identityAudit.confirm)identityAuditCancelConfirmation();else identityAuditClose();return;}if(event.key==='Tab'){const dialog=document.querySelector('.identity-audit-confirm-dialog')||document.querySelector('.identity-audit-dialog'),controls=[...dialog.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled),first=controls[0],last=controls.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
const identityAuditParams=new URLSearchParams(location.search);
if(section==='identity'&&identityAuditParams.get('review')==='1'){
 identityAuditOpen(identityAuditParams.get('auditType')==='续期'?identityExamples[identityKind].findIndex(r=>r.type==='续期'):0);
 if(identityTypes.includes(identityAuditParams.get('auditType')))identityAuditSwitch(identityAuditParams.get('auditType'));
}

function identityPendingCounts(kind){return identityExamples[kind].reduce((counts,r,index)=>{if(!identityDecisions[kind+'.'+index])counts[r.type]=(counts[r.type]||0)+1;return counts;},Object.fromEntries(identityTypes.map(type=>[type,0])));}
function identityPendingTags(kind){const counts=identityPendingCounts(kind),selected=identityView().filters.type||'';return `<div class="identity-pending-tags" aria-label="各审核类型待审核数量" ${req('identity.review.'+kind+'.counts')}>${identityTypes.map(type=>`<button type="button" class="identity-pending-tag ${selected===type?'active':''}" aria-pressed="${selected===type}" onclick="identityFilterType('${type}')">${type}<b>${counts[type]}</b></button>`).join('')}</div>`;}
function identityFilterType(type){const v=identityView(),next=v.filters.type===type?'':type;v.draft.type=next;v.filters={...v.filters,type:next};v.page=1;identityRender();}
function identityAuditHistoryPanel(){const a=identityAudit;return `<section class="identity-audit-section identity-history-panel" ${identityAuditModule('history')}><div class="identity-audit-section-title"><div><h2>${esc(a.row.name)} · 审核历史记录</h2></div></div><div class="identity-audit-history-filter"><label>审核类型 <select aria-label="历史记录审核类型" onchange="identityAudit.historyType=this.value;identityAuditRender()">${['全部',...identityTypes,'冻结操作'].map(type=>`<option ${a.historyType===type?'selected':''}>${type}</option>`).join('')}</select></label></div><div class="identity-audit-history-scroll"><table><thead><tr><th>审核／操作类型</th><th>结果</th><th>审核／操作人</th><th>审核／操作时间 ↓</th><th>审核意见／操作原因</th></tr></thead><tbody>${identityAuditHistory().map(h=>`<tr><td>${h.type}</td><td><span class="identity-badge ${h.result==='通过'?'green':h.result==='驳回'?'red':'orange'}">${h.result}</span></td><td>${h.operator}</td><td>${h.date}</td><td>${esc(h.opinion)}</td></tr>`).join('')||'<tr><td colspan="5">暂无审核记录</td></tr>'}</tbody></table></div></section>`;}
function identityUnfreezeFields(){const a=identityAudit,data=window.IdentityWorkflowData.unfreeze(a.kind,a.row);return `<dl class="identity-unfreeze-fields"><dt><em class="identity-required">*</em>冻结原因</dt><dd>${esc(data.freezeReason||'未提供')}</dd><dt><em class="identity-required">*</em>申诉说明</dt><dd>${esc(data.reason||'未提供')}</dd><dt><em class="identity-required">*</em>申诉联系电话</dt><dd>${esc(data.phone||'未提供')}</dd></dl>`;}
function identityAgentPermissionBlock(group){return `<div class="identity-audit-info-group identity-agent-permissions"><h3><em class="identity-required">*</em>${group.title}</h3><table><thead><tr><th>权限名称</th><th>数据范围</th></tr></thead><tbody>${group.rows.map(([permission,scope])=>`<tr><td>${esc(permission)}</td><td>${esc(scope)}</td></tr>`).join('')}</tbody></table></div>`;}
function identityAgentSignatureBlock(group){return `<div class="identity-audit-info-group identity-agent-signature"><h3>${group.title}</h3><dl>${group.rows.map(([name,value])=>`<div><dt><em class="identity-required">*</em>${name}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></div>`;}

function identityAuditConfirmation(){const a=identityAudit,draft=identityAuditDraft();return `<div class="identity-audit-confirm-veil"><section class="identity-audit-confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="identity-confirm-title" tabindex="-1" data-req-page="${identityPage()}" data-req-layer="dialog" data-req-surface="identity.review.${a.kind}.audit.confirm" data-req-title="提交审核确认" ${identityAuditModule('decision','decision.confirm')}><div class="identity-confirm-heading"><span class="identity-confirm-icon">!</span><h2 id="identity-confirm-title">确认提交审核？</h2><button type="button" aria-label="关闭审核确认" onclick="identityAuditCancelConfirmation()">×</button></div><div class="identity-confirm-body"><p>确认<strong>${esc(draft.result)}</strong>以下${esc(a.type)}申请？</p><dl><div><dt>审核对象</dt><dd>${esc(a.row.name)}</dd></div><div><dt>主体类型</dt><dd>${identityKinds[a.kind]}</dd></div><div><dt>审核类型</dt><dd>${esc(a.type)}</dd></div><div><dt>审核结果</dt><dd><span class="identity-badge ${draft.result==='通过'?'green':'red'}">${esc(draft.result)}</span></dd></div>${a.type==='续期'?`<div><dt>当前到期时间</dt><dd>${esc(a.row.renewal?.expiry||'未提供')}</dd></div><div><dt>申请续期时长</dt><dd>${esc(String(a.row.renewal?.days||''))} 天</dd></div><div><dt>${draft.result==='通过'?'通过后到期时间':'驳回后到期时间'}</dt><dd>${esc(draft.result==='通过'?identityRenewalDate(a.row.renewal.expiry,a.row.renewal.days):a.row.renewal.expiry)}</dd></div>`:''}${draft.opinion.trim()?`<div><dt>审核意见</dt><dd>${esc(draft.opinion.trim())}</dd></div>`:''}</dl></div><div class="identity-confirm-footer"><button type="button" class="btn" data-confirm-cancel onclick="identityAuditCancelConfirmation()">取消</button><button type="button" class="btn ${draft.result==='驳回'?'identity-audit-reject':'primary'}" onclick="identityAuditSubmit()">确认提交</button></div></section></div>`;}
function identityAuditCancelConfirmation(){if(!identityAudit)return;identityAudit.confirm=false;identityAuditRender();document.querySelector('#identity-audit-form button[type="submit"]')?.focus();}

function identityRenewalFields(){
 const a=identityAudit,r=a.row.renewal||{firstRenewal:'',expiry:'2026-11-12',days:180,reason:'申请延长主体身份有效期。'},result=a.row.result;
 const expiry=a.readOnly?(r.effectiveExpiry||(result==='驳回'?r.expiry:identityRenewalDate(r.expiry,r.days,(a.row.reviewedAt||'2026-11-06').slice(0,10)))):identityRenewalDate(r.expiry,r.days);
 return `<dl class="identity-audit-fields identity-renewal-fields" ${identityAuditModule('request','renewal.fields')}><div><dt>首次续期时间</dt><dd>${esc(r.firstRenewal||'暂无（首次申请）')}</dd></div><div><dt>当前到期时间</dt><dd>${esc(r.expiry)}</dd></div><div><dt>申请续期时长</dt><dd>${esc(String(r.days))} 天</dd></div><div><dt>${a.readOnly?'审核后到期时间':'预计续期后到期时间'}</dt><dd><strong>${esc(expiry)}</strong></dd></div><div class="wide"><dt>申请说明</dt><dd>${esc(r.reason||'—')}</dd></div></dl>`;
}
